style.css:
/* Fondo general */
body {
    background: linear-gradient(180deg, #2b1d3a, #1a1225) !important;
}

/* Barra superior */
ytd-masthead {
    background: rgba(40, 20, 60, 0.9) !important;
    backdrop-filter: blur(10px);
}

/* Tarjetas de videos */
ytd-rich-item-renderer,
ytd-video-renderer {
    background-color: rgba(255, 255, 255, 0.05) !important;
    border-radius: 15px !important;
    padding: 10px;
}

/* Texto */
body, yt-formatted-string {
    color: #e6d6ff !important;
}

/* Botones */
yt-icon-button {
    color: #caa6ff !important;
}

/* Hover (cuando pasas el mouse) */
ytd-rich-item-renderer:hover {
    transform: scale(1.03);
    transition: 0.3s;
}

/* Scrollbar bonita */
::-webkit-scrollbar {
    width: 8px;
}
::-webkit-scrollbar-thumb {
    background: #a46bff;
    border-radius: 10px;
}
